#!/usr/bin/env node
// Assembles app/ for one configuration: `npm run configure -- <name>`.
//
// A configuration lives in configuration/<name>/. Its manifest.json names the
// function that registers its parts with the platform registries, and its
// pages/ mirror app/: every pages/**/page.tsx and layout.tsx gets a one-line
// route wrapper at the same path under app/, which Next.js routes and splits
// like any other page. app/configuration.ts calls the registration; the
// layouts import it before any page reads the registries.
//
// "none" is the platform alone. The generated files are not committed: this
// script lists them in app/.gitignore, removes them when another
// configuration is assembled and never overwrites a platform file.
//
// The name comes from the argument, else METAPUS_CONFIGURATION, else the
// configuration assembled last, else "none". The npm scripts that read app/
// (dev, build, lint, typecheck, tests) run it first.
"use strict"
const { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, rmdirSync, statSync, writeFileSync } = require("node:fs")
const { dirname, join, relative, sep } = require("node:path")

const root = join(__dirname, "..")
const NONE = "none"
const ignoreFile = join("app", ".gitignore")
const selectionMarker = "# configuration: "
const routeFiles = new Set(["page.tsx", "layout.tsx"])
const validName = /^[a-z][a-z0-9_]{0,39}$/

const toPosix = path => path.split(sep).join("/")

/** The configurations with a frontend: configuration/<name>/manifest.json. */
function configurations(base = root) {
  const dir = join(base, "configuration")
  if (!existsSync(dir)) return []
  return readdirSync(dir).filter(name => existsSync(join(dir, name, "manifest.json"))).sort()
}

function walk(base, dir) {
  return readdirSync(join(base, dir)).flatMap(name => {
    const path = join(dir, name)
    return statSync(join(base, path)).isDirectory() ? walk(base, path) : [path]
  })
}

/**
 * The files app/ holds for configuration name, as a map from the path
 * relative to the frontend root to the content.
 */
function plan(name, base = root) {
  if (!validName.test(name)) throw new Error(`configuration name ${JSON.stringify(name)} is not a lowercase identifier`)
  const files = new Map()
  if (name === NONE) {
    files.set(join("app", "configuration.ts"), [
      "// Generated by `npm run configure -- none`: the platform without a",
      "// configuration registers nothing.",
      "export {}",
      "",
    ].join("\n"))
    return files
  }
  const manifestPath = join(base, "configuration", name, "manifest.json")
  if (!existsSync(manifestPath)) {
    throw new Error(`configuration/${name}/manifest.json is missing; known configurations: ${[NONE, ...configurations(base)].join(", ")}`)
  }
  const manifest = JSON.parse(readFileSync(manifestPath, "utf8"))
  if (typeof manifest.register !== "string" || !/^[A-Za-z_$][\w$]*$/.test(manifest.register)) {
    throw new Error(`configuration/${name}/manifest.json: "register" must name the function configuration/${name}/index.ts exports`)
  }
  files.set(join("app", "configuration.ts"), [
    `// Generated by \`npm run configure -- ${name}\` from configuration/${name}/manifest.json.`,
    "// app/ is the composition root: platform code reaches the configuration's",
    "// parts only through what this registers.",
    `import { ${manifest.register} } from "@/configuration/${name}"`,
    "",
    `${manifest.register}()`,
    "",
  ].join("\n"))
  const pages = join("configuration", name, "pages")
  if (existsSync(join(base, pages))) {
    for (const file of walk(base, pages)) {
      const fileName = file.split(sep).at(-1)
      if (!routeFiles.has(fileName)) {
        if (/\.(tsx?|jsx?)$/.test(fileName)) throw new Error(`${toPosix(file)}: pages/ holds only page.tsx and layout.tsx; move other modules next to the configuration's components`)
        continue
      }
      const route = relative(pages, file)
      const target = toPosix(file).replace(/\.tsx$/, "")
      files.set(join("app", route), `export { default } from "@/${target}"\n`)
    }
  }
  return files
}

/** The configuration assembled last and the files it generated. */
function current(base = root) {
  const path = join(base, ignoreFile)
  if (!existsSync(path)) return { name: undefined, files: [] }
  const lines = readFileSync(path, "utf8").split("\n")
  const marker = lines.find(line => line.startsWith(selectionMarker))
  const files = lines.filter(line => line.startsWith("/") && line !== "/.gitignore")
    .map(line => join("app", ...line.slice(1).replace(/\\(.)/g, "$1").split("/")))
  return { name: marker?.slice(selectionMarker.length).trim(), files }
}

// gitignore patterns treat these characters specially; route segments such
// as [id] must match literally.
const escapeIgnore = path => path.replace(/[\\[\]*?!#]/g, "\\$&")

function pruneEmptyDirs(base, dir) {
  while (dir !== "app" && dir !== "." && existsSync(join(base, dir)) && readdirSync(join(base, dir)).length === 0) {
    rmdirSync(join(base, dir))
    dir = dirname(dir)
  }
}

/** Assembles app/ for configuration name and returns the files written. */
function configure(name, base = root) {
  const files = plan(name, base)
  const previous = current(base)
  const owned = new Set(previous.files)
  for (const [path, content] of files) {
    const full = join(base, path)
    if (existsSync(full) && !owned.has(path) && readFileSync(full, "utf8") !== content) {
      throw new Error(`${toPosix(path)} is a platform file; configuration/${name}/pages must not shadow it`)
    }
  }
  for (const path of previous.files) {
    if (files.has(path)) continue
    rmSync(join(base, path), { force: true })
    pruneEmptyDirs(base, dirname(path))
  }
  for (const [path, content] of files) {
    mkdirSync(dirname(join(base, path)), { recursive: true })
    writeFileSync(join(base, path), content)
  }
  // Next.js generates route types from app/ into .next; those of the
  // previous configuration name routes that are gone.
  if (previous.name !== name) {
    for (const types of [join(".next", "types"), join(".next", "dev", "types")]) rmSync(join(base, types), { recursive: true, force: true })
  }
  const ignored = [...files.keys()].map(path => "/" + escapeIgnore(toPosix(relative("app", path)))).sort()
  writeFileSync(join(base, ignoreFile), [
    "# Generated by scripts/configure.cjs: the files it assembled for one",
    "# configuration. Do not edit; run `npm run configure -- <name>`.",
    selectionMarker + name,
    "/.gitignore",
    ...ignored,
    "",
  ].join("\n"))
  return [...files.keys()]
}

module.exports = { NONE, configurations, configure, current, plan, root }

if (require.main === module) {
  const name = process.argv[2] || process.env.METAPUS_CONFIGURATION || current().name || NONE
  try {
    const written = configure(name)
    console.log(`configuration ${name}: ${written.length} files in app/`)
  } catch (error) {
    console.error(`configure: ${error.message}`)
    process.exit(1)
  }
}
